 co=counts[n];lecture=f'lectures/iscarb/Ch{n}-{c["slug"]}.html';step=['Bound a claim','Measure','Trace a hazard','Test a misuse case','Plan recovery','Compare options','Specify a contract','Handle a remote failure','Integrate across owners'][i-1]
 body+=f'''<article class="lesson" id="chapter-{n}" aria-labelledby="title-{n}"><div class="chapter-number">{i:02d}<small>CH {n}</small></div><div class="chapter-content"><div class="chapter-heading"><h3 id="title-{n}">{c['title']}</h3><span class="unit-count">{co['classroom_units']} units</span></div><p>{c['challenge']}</p><div class="meta"><span>{co['source_slide_count']} source slides</span><span>Assignment {i}: {step}</span></div><div class="actions"><a class="btn" href="{lecture}#START">Open chapter</a><a class="btn secondary" href="fbr-submission.html?chapter={n}">Assignment {i}</a><a class="text-link" href="{lecture}#C01">Source map</a><a class="text-link" href="{lecture}" download>HTML ↓</a></div><label class="check"><input type="checkbox" class="review-check" data-review-chapter="{n}">I have reviewed this chapter</label><div class="review-status small" role="status">Your review mark stays on this device.</div></div></article>'''
